        syntheticStack[0] = element;
        for (int n = 1; n < elementsToAdd; n++) {
          syntheticStack[n] =
              (stackGetter != null)
                  ? stackGetter.getStackTraceElement(throwable, index + n)
                  : stack[index + n];
        }
        return syntheticStack;
      }
    }
    return new StackTraceElement[0];
  }
}

